import React, { useState, useEffect, useRef } from 'react';
import { Card, api } from '../App';

export default function ReportsPage() {
  const [saleNos,      setSaleNos]      = useState([]);
  const [selSale,      setSelSale]      = useState('');
  const [selBatch,     setSelBatch]     = useState('');
  const [activeTab,    setActiveTab]    = useState('party');

  // Party report
  const [partyData,    setPartyData]    = useState([]);
  const [expanded,     setExpanded]     = useState(null);
  const [loadingParty, setLoadingParty] = useState(false);

  // Market report — multi-sale
  const [selSalesForMkt, setSelSalesForMkt] = useState([]);   // array of sale_no strings
  const [marketDataMap,  setMarketDataMap]  = useState({});   // { sale_no: [...rows] }
  const [mktGarden,      setMktGarden]      = useState('');
  const [loadingMkt,     setLoadingMkt]     = useState(false);
  const [mktError,       setMktError]       = useState('');

  const printRef = useRef(null);

  /* ── Load sale numbers ──────────────────────────────────────────────────── */
  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => {
        setSaleNos(r.data);
        if (r.data[0]) {
          const first = String(r.data[0].sale_no);
          const firstBatch = r.data[0].batch_name || '';
          setSelSale(first);
          setSelBatch(firstBatch);
          setSelSalesForMkt([`${first}||${firstBatch}`]);
        }
      })
      .catch(() => {});
  }, []);

  /* ── Party report loader ────────────────────────────────────────────────── */
  const loadPartyReport = async () => {
    if (!selSale) return;
    setLoadingParty(true);
    const bParam = selBatch ? `&batch_name=${encodeURIComponent(selBatch)}` : '';
    try {
      const r = await api.get(`/reports/party-summary?sale_no=${selSale}${bParam}`);
      setPartyData(r.data);
    } catch (e) {
      alert(e.response?.data?.error || e.message);
    } finally {
      setLoadingParty(false);
    }
  };

  /* ── Market report loader (multi-sale+batch) ──────────────────────────── */
  const loadMarketReport = async (salesArr) => {
    if (!salesArr || salesArr.length === 0) return;
    setLoadingMkt(true);
    setMktError('');
    try {
      const results = await Promise.all(
        salesArr.map(combo => {
          const [sno, batch] = combo.split('||');
          const bParam = batch ? `&batch_name=${encodeURIComponent(batch)}` : '';
          const label = batch ? `${sno}__${batch}` : sno;
          return api.get(`/reports/market?sale_no=${sno}${bParam}`)
            .then(r => ({ label, data: r.data }))
            .catch(() => ({ label, data: [] }));
        })
      );
      const map = {};
      results.forEach(({ label, data }) => { map[label] = data; });
      setMarketDataMap(map);
      const allEmpty = results.every(r => r.data.length === 0);
      if (allEmpty) setMktError('No sold list data found for the selected sale(s). Please upload Sold List first.');
    } catch (e) {
      setMktError(e.response?.data?.error || e.message);
    } finally {
      setLoadingMkt(false);
    }
  };

  /* ── Auto-load on tab / sale change ────────────────────────────────────── */
  useEffect(() => {
    if (!selSale) return;
    if (activeTab === 'party') loadPartyReport();
  }, [selSale, selBatch, activeTab]); // eslint-disable-line

  useEffect(() => {
    if (activeTab === 'market' && selSalesForMkt.length > 0) loadMarketReport(selSalesForMkt);
  }, [activeTab]); // eslint-disable-line

  /* ── Toggle sale+batch selection for market report ─────────────────────── */
  const toggleMktSale = (combo) => {
    setSelSalesForMkt(prev => {
      const next = prev.includes(combo) ? prev.filter(s => s !== combo) : [...prev, combo];
      return next;
    });
  };

  const applyMktSales = () => {
    if (selSalesForMkt.length === 0) { setMktError('Please select at least one sale.'); return; }
    loadMarketReport(selSalesForMkt);
  };

  /* ── Build garden-wise combined structure ───────────────────────────────── */
  // Shape: { garden: { origin, grades: { grade: { [sale_no]: { low, high } } } } }
  const buildGardenMap = () => {
    const gardenMap = {};
    Object.entries(marketDataMap).forEach(([label, rows]) => {
      rows.forEach(row => {
        const g = row.garden || '—';
        if (!gardenMap[g]) gardenMap[g] = { origin: row.origin || '—', grades: {} };
        const grade = row.grade || '—';
        if (!gardenMap[g].grades[grade]) gardenMap[g].grades[grade] = {};
        gardenMap[g].grades[grade][label] = {
          low:  parseFloat(row.price_low)  || 0,
          high: parseFloat(row.price_high) || 0,
        };
      });
    });
    return gardenMap;
  };

  const gardenMap   = buildGardenMap();
  const allGardens  = Object.keys(gardenMap).sort();
  const filteredGardens = mktGarden ? allGardens.filter(g => g === mktGarden) : allGardens;
  const activeSales = Object.keys(marketDataMap).filter(label => (marketDataMap[label]||[]).length > 0).sort();

  // Format a label like "15__CTC Lot" → "Sale #15 (CTC Lot)" or "15" → "Sale #15"
  const fmtLabel = (label) => {
    if (!label) return '';
    const parts = label.split('__');
    if (parts.length === 2 && parts[1]) return `Sale #${parts[0]} (${parts[1]})`;
    return `Sale #${parts[0]}`;
  };

  /* ── helpers ────────────────────────────────────────────────────────────── */
  // Format lot number: JT0063 → JT-63
  const fmtLot = (s) => {
    if (!s) return '—';
    const m = s.match(/^([A-Za-z]+)0*(\d+)$/);
    return m ? `${m[1]}-${m[2]}` : s;
  };

  // Render a min-max price cell (React)
  const PriceCell = ({ low, high }) => {
    const lo = parseFloat(low); const hi = parseFloat(high);
    if (isNaN(lo) || lo === 0) return <span style={{ color: '#ccc' }}>—</span>;
    if (lo === hi) return <span style={{ fontWeight: 700, color: '#1a7a4a' }}>₹{lo.toFixed(0)}</span>;
    return (
      <span style={{ whiteSpace: 'nowrap' }}>
        <span style={{ fontWeight: 700, color: '#1a7a4a' }}>₹{lo.toFixed(0)}</span>
        <span style={{ color: '#aaa', margin: '0 4px' }}>–</span>
        <span style={{ fontWeight: 700, color: '#c0392b' }}>₹{hi.toFixed(0)}</span>
      </span>
    );
  };

  // Build HTML price string for PDF
  const pdfPrice = (low, high) => {
    const lo = parseFloat(low); const hi = parseFloat(high);
    if (isNaN(lo) || lo === 0) return '—';
    if (lo === hi) return `<span style="color:#1a7a4a;font-weight:700">\u20B9${lo.toFixed(0)}</span>`;
    return `<span style="color:#1a7a4a;font-weight:700">\u20B9${lo.toFixed(0)}</span> \u2013 <span style="color:#c0392b;font-weight:700">\u20B9${hi.toFixed(0)}</span>`;
  };

  /* ── Party PDF — single party ───────────────────────────────────────────── */
  const partyPDFHtml = (party) => {
    const lotsRows = (party.lots || []).map((lot, i) => `
      <tr style="background:${i%2===0?'#fff':'#f9fafb'}">
        <td style="font-family:monospace;font-weight:700;color:#1e40af">${fmtLot(lot.invoice_no)}</td>
        <td style="font-weight:700;color:#1a3c5e">${lot.garden || ''}</td>
        <td style="color:#777;font-size:8px">${lot.origin || ''}</td>
        <td><span class="grade">${lot.grade || ''}</span></td>
        <td>${lot.broker || ''}</td>
        <td>${lot.invoice || ''}</td>
        <td>${lot.bags || ''}</td>
        <td>${lot.net_wt || ''}</td>
        <td style="text-align:right">${pdfPrice(lot.mkt_low, lot.mkt_high)}</td>
      </tr>`).join('');
    return `
      <div class="party-block">
        <div class="party-hdr">
          <span class="pcode">${party.party_code}</span>
          <span class="pname">${party.party_name}</span>
          <span class="plots">${party.total_lots} lots</span>
        </div>
        <table>
          <thead><tr>
            <th>Lot No</th><th>Garden</th><th>Origin</th><th>Grade</th>
            <th>Broker</th><th>Invoice</th><th>Bags</th><th>Net Wt</th>
            <th style="text-align:right">Mkt Price \u20B9 (Min\u2013Max)</th>
          </tr></thead>
          <tbody>${lotsRows}</tbody>
        </table>
      </div>`;
  };

  const pdfStyles = `
    body { font-family: Arial, sans-serif; font-size: 10px; margin: 12mm; color: #1a2533; }
    h1 { font-size: 13px; color: #1a3c5e; margin-bottom: 3px; }
    .party-block { margin-bottom: 12px; page-break-inside: avoid; }
    .party-hdr { background: #1a3c5e; color: #fff; padding: 4px 10px; display: flex; align-items: center; gap: 10px; border-radius: 3px 3px 0 0; }
    .pcode { background: rgba(255,255,255,0.2); padding: 1px 6px; border-radius: 8px; font-weight: 900; font-size: 11px; }
    .pname { font-weight: 700; font-size: 12px; flex: 1; }
    .plots { font-size: 10px; opacity: 0.8; }
    table { width: 100%; border-collapse: collapse; font-size: 9px; border: 1px solid #e2e8f0; }
    th { background: #f0f4f8; padding: 4px 6px; text-align: left; font-weight: 700; color: #444; }
    td { padding: 3px 6px; border-bottom: 1px solid #f0f4f8; }
    .grade { background: #dbeafe; color: #1e40af; padding: 1px 5px; border-radius: 8px; font-weight: 800; font-size: 8px; }
    @page { size: A4; margin: 8mm; }
    @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }`;

  /* ── All-parties PDF ────────────────────────────────────────────────────── */
  const downloadPartyPDF = () => {
    const win = window.open('', '_blank');
    const rowsHtml = partyData.map(p => partyPDFHtml(p)).join('');
    win.document.write(`<!DOCTYPE html><html><head><title>Party Report - Sale #${selSale}${selBatch ? ' - '+selBatch : ''}</title>
<style>${pdfStyles}</style></head><body>
<h1>Party Marking Report &mdash; Sale #${selSale}${selBatch ? ' &mdash; ' + selBatch : ''}</h1>
<p style="color:#888;font-size:9px;margin-bottom:8px;">Generated: ${new Date().toLocaleString('en-IN')} &nbsp;|&nbsp; ${partyData.length} parties &nbsp;|&nbsp; Market price (Min\u2013Max) from Sold List</p>
${rowsHtml}</body></html>`);
    win.document.close(); win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  /* ── Single-party PDF ───────────────────────────────────────────────────── */
  const downloadSinglePartyPDF = (party) => {
    const win = window.open('', '_blank');
    win.document.write(`<!DOCTYPE html><html><head><title>${party.party_code} - Sale #${selSale}${selBatch ? ' - '+selBatch : ''}</title>
<style>${pdfStyles}</style></head><body>
<h1>${party.party_name} (${party.party_code}) &mdash; Sale #${selSale}${selBatch ? ' &mdash; ' + selBatch : ''}</h1>
<p style="color:#888;font-size:9px;margin-bottom:8px;">Generated: ${new Date().toLocaleString('en-IN')} &nbsp;|&nbsp; ${party.total_lots} lots</p>
${partyPDFHtml(party)}</body></html>`);
    win.document.close(); win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  /* ── Market PDF ─────────────────────────────────────────────────────────── */
  const downloadMarketPDF = () => {
    if (filteredGardens.length === 0) return;
    const saleHeaders = activeSales.map(label => `<th class="right" style="background:#1a4c7e;">${fmtLabel(label)} Min\u2013Max \u20B9</th>`).join('');

    const bodyRows = filteredGardens.flatMap(garden => {
      const info   = gardenMap[garden];
      const grades = Object.keys(info.grades).sort();
      return grades.map((grade, gi) => {
        const saleCells = activeSales.map(label => {
          const d = info.grades[grade][label];
          if (!d) return `<td class="right" style="color:#ccc">—</td>`;
          if (d.low === d.high) return `<td class="right low">\u20B9${d.low.toFixed(0)}</td>`;
          return `<td class="right"><span class="low">\u20B9${d.low.toFixed(0)}</span> \u2013 <span class="high">\u20B9${d.high.toFixed(0)}</span></td>`;
        }).join('');
        return `<tr style="background:${gi%2===0?'#fff':'#f9fafb'}">
          ${gi === 0 ? `<td rowspan="${grades.length}" style="font-weight:700;color:#1a3c5e;vertical-align:top;padding-top:5px;border-right:2px solid #e2e8f0;">${garden}<br/><span style="font-size:8px;color:#888;font-weight:400">${info.origin}</span></td>` : ''}
          <td><span class="grade">${grade}</span></td>
          ${saleCells}
        </tr>`;
      });
    }).join('');

    const html = `<!DOCTYPE html><html><head><title>Market Report</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 10px; margin: 12mm; color: #1a2533; }
  h1 { font-size: 14px; color: #1a3c5e; }
  table { width: 100%; border-collapse: collapse; font-size: 9px; border: 1px solid #e2e8f0; }
  th { background: #1a3c5e; color: #fff; padding: 4px 6px; text-align: left; }
  th.right { text-align: right; }
  td { padding: 3px 6px; border-bottom: 1px solid #f0f4f8; }
  td.right { text-align: right; font-weight: bold; }
  .low { color: #1a7a4a; } .high { color: #c0392b; }
  .grade { background: #dbeafe; color: #1e40af; padding: 1px 5px; border-radius: 8px; font-weight: 800; font-size: 8px; }
  @page { size: A4 landscape; margin: 8mm; }
  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
</style></head><body>
<h1>Market Price Report &mdash; ${activeSales.map(l => fmtLabel(l)).join(', ')}</h1>
<p style="color:#888;font-size:9px;margin-bottom:8px;">Generated: ${new Date().toLocaleString('en-IN')} | Garden-wise Grade Min/Max</p>
<table>
  <thead>
    <tr><th>Garden</th><th>Grade</th>${saleHeaders}</tr>
  </thead>
  <tbody>${bodyRows}</tbody>
</table>
</body></html>`;

    const win = window.open('', '_blank');
    win.document.write(html);
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 600);
  };

  /* ── Styles ─────────────────────────────────────────────────────────────── */
  const tabBtn = (key) => ({
    padding: '8px 18px', borderRadius: 6, cursor: 'pointer', fontWeight: 600, fontSize: 13, border: 'none',
    background: activeTab === key ? '#1a3c5e' : '#f0f4f8',
    color:      activeTab === key ? '#fff'    : '#555',
  });
  const th  = (right) => ({ padding: '7px 10px', textAlign: right ? 'right' : 'left', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' });
  const td  = (extra) => ({ padding: '6px 10px', ...extra });
  const thD = (right) => ({ padding: '6px 8px', textAlign: right ? 'right' : 'left', fontWeight: 700, color: '#fff', whiteSpace: 'nowrap', background: '#1a3c5e', fontSize: 11 });

  /* ═══════════════════════════════════════════════════════════════════════════
     RENDER
  ═══════════════════════════════════════════════════════════════════════════ */
  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>📊 Reports</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Party marking report and market price report from sold list.</p>

      {/* ── Controls ── */}
      <Card style={{ marginBottom: 16, padding: 14 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
          <div>
            <label style={{ fontSize: 11, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 0.4, marginBottom: 4, display: 'block' }}>
              Sale / Batch
            </label>
            <select value={selSale ? `${selSale}||${selBatch}` : ''} onChange={e => {
              const [s, b] = (e.target.value || '').split('||');
              setSelSale(s || ''); setSelBatch(b || '');
            }}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 280 }}>
              <option value="">Select sale...</option>
              {saleNos.map(s => {
                const val = `${s.sale_no}||${s.batch_name || ''}`;
                const label = s.batch_name
                  ? `Sale ${s.sale_no} — ${s.batch_name} (${s.lot_count} lots)`
                  : `Sale ${s.sale_no} (${s.lot_count} lots)`;
                return <option key={val} value={val}>{label}</option>;
              })}
            </select>
          </div>
          <div style={{ display: 'flex', gap: 8, marginLeft: 'auto' }}>
            <button style={tabBtn('party')}  onClick={() => setActiveTab('party')}>👥 Party Report</button>
            <button style={tabBtn('market')} onClick={() => setActiveTab('market')}>📈 Market Report</button>
          </div>
        </div>
      </Card>

      {/* ════════════════════════════════════════════════════════════════════
          PARTY REPORT
      ════════════════════════════════════════════════════════════════════ */}
      {activeTab === 'party' && (
        <Card>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
            <h3 style={{ fontSize: 15 }}>Party Marking Report — Sale #{selSale}{selBatch && <span style={{ fontSize: 12, color: '#6b7280', marginLeft: 6 }}>({selBatch})</span>}</h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <span style={{ fontSize: 12, color: '#888' }}>{partyData.length} parties</span>
              {partyData.length > 0 && (
                <button onClick={downloadPartyPDF}
                  style={{ padding: '6px 14px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 12 }}>
                  📄 All Parties PDF
                </button>
              )}
            </div>
          </div>

          {loadingParty && <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading...</div>}

          {!loadingParty && partyData.length === 0 && (
            <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No markings for Sale #{selSale}{selBatch && ` / "${selBatch}"`}</div>
          )}

          {!loadingParty && partyData.map(party => {
            const isExp = expanded === party.party_code;
            const rowBg    = isExp ? '#1a3c5e' : '#f8fafc';
            const rowColor = isExp ? '#fff'    : '#1a3c5e';
            const badgeBg  = isExp ? 'rgba(255,255,255,0.2)' : '#dbeafe';
            const badgeClr = isExp ? '#fff' : '#1e40af';
            const cntColor = isExp ? '#90cdf4' : '#1a7a4a';

            return (
              <div key={party.party_code} style={{ marginBottom: 8, border: '1.5px solid #e2e8f0', borderRadius: 8, overflow: 'hidden' }}>
                {/* Header row */}
                <div style={{ padding: '10px 16px', background: rowBg, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  {/* Left: click to expand */}
                  <div onClick={() => setExpanded(isExp ? null : party.party_code)}
                    style={{ display: 'flex', alignItems: 'center', gap: 12, cursor: 'pointer', flex: 1 }}>
                    <span style={{ background: badgeBg, color: badgeClr, padding: '2px 10px', borderRadius: 99, fontSize: 12, fontWeight: 700 }}>
                      {party.party_code}
                    </span>
                    <span style={{ fontWeight: 700, fontSize: 14, color: rowColor }}>{party.party_name}</span>
                    <span style={{ fontSize: 13, fontWeight: 700, color: cntColor }}>{party.total_lots} lots</span>
                    <span style={{ color: isExp ? '#fff' : '#888', fontSize: 12 }}>{isExp ? '▲' : '▼'}</span>
                  </div>
                  {/* Right: per-party PDF */}
                  <button
                    onClick={(e) => { e.stopPropagation(); downloadSinglePartyPDF(party); }}
                    style={{ padding: '4px 10px', background: isExp ? 'rgba(255,255,255,0.15)' : '#e8f0fe', color: isExp ? '#fff' : '#1a3c5e', border: 'none', borderRadius: 5, cursor: 'pointer', fontWeight: 700, fontSize: 11, whiteSpace: 'nowrap' }}>
                    📄 PDF
                  </button>
                </div>

                {/* Expanded detail — one row per lot */}
                {isExp && (
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                      <thead>
                        <tr style={{ background: '#f0f4f8' }}>
                          {['Lot No', 'Garden (Mark)', 'Origin', 'Grade', 'Broker', 'Invoice', 'Bags', 'Net Wt', 'Mkt Price ₹ (Min–Max)'].map(h => (
                            <th key={h} style={th(h === 'Mkt Price ₹ (Min–Max)')}>{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {(party.lots || []).map((lot, i) => (
                          <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                            <td style={td({ fontFamily: 'monospace', fontWeight: 700, color: '#1e40af', fontSize: 11 })}>
                              {fmtLot(lot.invoice_no)}
                            </td>
                            <td style={td({ fontWeight: 700, color: '#1a3c5e' })}>{lot.garden}</td>
                            <td style={td({ fontSize: 11, color: '#777' })}>{lot.origin || '—'}</td>
                            <td style={td()}>
                              <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{lot.grade}</span>
                            </td>
                            <td style={td({ color: '#555' })}>{lot.broker || '—'}</td>
                            <td style={td({ fontFamily: 'monospace', fontSize: 11, color: '#888' })}>{lot.invoice || '—'}</td>
                            <td style={td()}>{lot.bags || '—'}</td>
                            <td style={td()}>{lot.net_wt || '—'}</td>
                            <td style={td({ textAlign: 'right' })}>
                              <PriceCell low={lot.mkt_low} high={lot.mkt_high} />
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            );
          })}
        </Card>
      )}

      {/* ════════════════════════════════════════════════════════════════════
          MARKET REPORT
      ════════════════════════════════════════════════════════════════════ */}
      {activeTab === 'market' && (
        <div>
          {/* Sale selector panel */}
          <Card style={{ marginBottom: 12, padding: 14 }}>
            <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start', flexWrap: 'wrap' }}>
              <div>
                <div style={{ fontSize: 11, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 0.4, marginBottom: 6 }}>
                  Select Sale(s) for Market Report
                </div>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  {saleNos.map(s => {
                    const combo = `${s.sale_no}||${s.batch_name || ''}`;
                    const sel   = selSalesForMkt.includes(combo);
                    const chipLabel = s.batch_name
                      ? `Sale #${s.sale_no} — ${s.batch_name}`
                      : `Sale #${s.sale_no}`;
                    return (
                      <button key={combo} onClick={() => toggleMktSale(combo)}
                        style={{
                          padding: '5px 14px', borderRadius: 20, fontSize: 12, fontWeight: 600, cursor: 'pointer', border: '1.5px solid',
                          borderColor: sel ? '#1a3c5e' : '#cbd5e0',
                          background:  sel ? '#1a3c5e' : '#fff',
                          color:       sel ? '#fff'    : '#555',
                        }}>
                        {chipLabel}
                      </button>
                    );
                  })}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end', marginLeft: 'auto', flexWrap: 'wrap' }}>
                {allGardens.length > 0 && (
                  <div>
                    <div style={{ fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4 }}>Filter Garden</div>
                    <select value={mktGarden} onChange={e => setMktGarden(e.target.value)}
                      style={{ padding: '7px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, minWidth: 160 }}>
                      <option value="">All Gardens</option>
                      {allGardens.map(g => <option key={g} value={g}>{g}</option>)}
                    </select>
                  </div>
                )}
                <button onClick={applyMktSales}
                  style={{ padding: '7px 18px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13 }}>
                  Load Report
                </button>
                {activeSales.length > 0 && (
                  <button onClick={downloadMarketPDF}
                    style={{ padding: '7px 16px', background: '#1a7a4a', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13 }}>
                    📄 Download PDF
                  </button>
                )}
              </div>
            </div>
          </Card>

          <Card>
            <div style={{ marginBottom: 10, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <h3 style={{ fontSize: 15 }}>
                  Market Price Report
                  {activeSales.length > 0 && ` — ${activeSales.map(l => fmtLabel(l)).join(', ')}`}
                </h3>
                <div style={{ fontSize: 12, color: '#888', marginTop: 2 }}>Garden-wise grade prices (Low / High) from Sold List</div>
              </div>
              {activeSales.length > 0 && (
                <span style={{ fontSize: 12, color: '#888' }}>{filteredGardens.length} gardens</span>
              )}
            </div>

            {loadingMkt && <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading market data...</div>}

            {!loadingMkt && mktError && (
              <div style={{ padding: 16, background: '#fff5f5', border: '1px solid #fed7d7', borderRadius: 8, color: '#c0392b', fontSize: 13 }}>
                ⚠️ {mktError}
              </div>
            )}

            {!loadingMkt && !mktError && activeSales.length === 0 && (
              <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>
                Select one or more sales above and click <strong>Load Report</strong>.
              </div>
            )}

            {!loadingMkt && !mktError && filteredGardens.length > 0 && (
              <div style={{ overflowX: 'auto' }} ref={printRef}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                  <thead>
                    <tr>
                      <th style={thD(false)}>Garden (Mark)</th>
                      <th style={thD(false)}>Origin</th>
                      <th style={thD(false)}>Grade</th>
                      {activeSales.map(label => (
                        <th key={label} style={{ ...thD(true), background: '#1a4c7e' }}>{fmtLabel(label)} Min–Max ₹</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {filteredGardens.map(garden => {
                      const info   = gardenMap[garden];
                      const grades = Object.keys(info.grades).sort();
                      return grades.map((grade, gi) => (
                        <tr key={`${garden}-${grade}`} style={{ borderBottom: '1px solid #f0f4f8', background: gi % 2 === 0 ? '#fff' : '#fafbfc' }}>
                          {gi === 0 && (
                            <td rowSpan={grades.length}
                              style={{ padding: '8px 10px', fontWeight: 700, color: '#1a3c5e', verticalAlign: 'top', borderRight: '2px solid #e2e8f0', borderBottom: '2px solid #e2e8f0' }}>
                              {garden}
                            </td>
                          )}
                          {gi === 0 && (
                            <td rowSpan={grades.length}
                              style={{ padding: '8px 10px', fontSize: 11, color: '#777', verticalAlign: 'top', borderRight: '1px solid #e2e8f0', borderBottom: '2px solid #e2e8f0' }}>
                              {info.origin}
                            </td>
                          )}
                          <td style={td()}>
                            <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>
                              {grade}
                            </span>
                          </td>
                          {activeSales.map(label => {
                            const d = info.grades[grade][label];
                            const same = d && d.low === d.high;
                            return (
                              <td key={label} style={td({ textAlign: 'right', whiteSpace: 'nowrap' })}>
                                {d ? (
                                  same
                                    ? <span style={{ fontWeight: 700, color: '#1a7a4a' }}>₹{d.low.toFixed(0)}</span>
                                    : <span>
                                        <span style={{ fontWeight: 700, color: '#1a7a4a' }}>₹{d.low.toFixed(0)}</span>
                                        <span style={{ color: '#aaa', margin: '0 4px' }}>–</span>
                                        <span style={{ fontWeight: 700, color: '#c0392b' }}>₹{d.high.toFixed(0)}</span>
                                      </span>
                                ) : <span style={{ color: '#ccc' }}>—</span>}
                              </td>
                            );
                          })}
                        </tr>
                      ));
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      )}
    </div>
  );
}
